// GENERATED by build.sh -- edit tests/canvas2d-readback/test.js, not this file.
// Conformance harness: how a test says what it found.
//
// The result channel is `console.error` with a structured prefix. That looks
// crude and it is the deliberate choice: it is the ONE channel that already
// works identically on every platform Migo runs on -- Android through JNI,
// C-ABI hosts with no JVM, the Linux player, Windows -- with no new platform
// surface to build, maintain, or forget to port. (`console.log` is filtered by
// EMUI on real Huawei devices; `console.error` is not.)
//
// Everything below is deliberately dependency-free and runs inside the game
// bundle, because the whole point is that the same bundle produces the same
// verdict wherever it runs.
//
// The API these bundles call is `migo.*`, not `wx.*`. `migo` is the only
// capability surface the engine installs; the mini-game-platform globals come
// from a separate adapter package that a host loads if it wants them. Bundles
// here written against `wx` stopped running entirely when that namespace left
// the engine -- every test died on `ReferenceError: wx is not defined` before
// its first assertion, and the suite reported "0 assertions" rather than a
// failure anyone would read as one. A suite must test the engine's own surface,
// or it tests whichever adapter happened to be loaded.

(() => {
    const PREFIX = "[conformance]";
    const results = [];
    let finished = false;

    const emit = (line) => console.error(PREFIX, line);

    /// Report one assertion. `detail` should carry the numbers, not just a verdict:
    /// a failure that says "expected #ff00ff, got #000000 at (360,640)" is
    /// actionable from a log file on a device you cannot attach a debugger to.
    function check(id, passed, detail) {
        results.push({ id, passed: !!passed });
        emit(`${passed ? "PASS" : "FAIL"} ${id} ${detail || ""}`.trimEnd());
    }

    /// Compare two pixel buffers that must be identical *within this run*.
    ///
    /// This is the reftest primitive, and it is the most valuable one here: it is
    /// platform-independent by construction. Two ways of drawing the same thing
    /// must agree, whatever the GPU does to both of them -- so it survives Mali vs
    /// Adreno vs SwiftShader vs ANGLE, where a golden image cannot.
    function checkSameRender(id, a, b, tolerance) {
        const tol = tolerance || 0;
        if (a.length !== b.length) {
            check(id, false, `buffer lengths differ: ${a.length} vs ${b.length}`);
            return;
        }
        let worst = 0;
        let worstAt = -1;
        for (let i = 0; i < a.length; i++) {
            const d = Math.abs(a[i] - b[i]);
            if (d > worst) { worst = d; worstAt = i; }
        }
        check(
            id,
            worst <= tol,
            worst <= tol
                ? `max channel delta ${worst} <= ${tol}`
                : `max channel delta ${worst} > ${tol} at byte ${worstAt} (px ${Math.floor(worstAt / 4)})`,
        );
    }

    /// Assert one pixel. Sampling beats whole-frame comparison for geometry and
    /// colour: it says which pixel was wrong, and it does not care how the driver
    /// anti-aliased the edge two pixels away.
    function checkPixel(id, ctx, x, y, expected, tolerance) {
        const tol = tolerance === undefined ? 2 : tolerance;
        const px = ctx.getImageData(x, y, 1, 1).data;
        const got = [px[0], px[1], px[2], px[3]];
        const ok = expected.every((want, i) => Math.abs(got[i] - want) <= tol);
        check(id, ok, `at (${x},${y}) want [${expected}] +/-${tol}, got [${got}]`);
    }

    /// End the run. The runner keys off these lines rather than an exit code,
    /// because several of the hosts that must run this suite (a NativeActivity, an
    /// embedded session inside someone else's app) have no exit code to give.
    function done() {
        if (finished) return;
        finished = true;
        const failed = results.filter((r) => !r.passed);
        emit(`SUMMARY total=${results.length} failed=${failed.length}`);
        if (failed.length) emit(`FAILED-IDS ${failed.map((r) => r.id).join(",")}`);
        emit("DONE");
    }

    /// Run test bodies in order, then report. A throw is a failure with the message
    /// attached rather than a silent stop: a suite that dies quietly on one
    /// platform reads exactly like a suite that never ran.
    function run(tests) {
        // One test per frame, not all of them in one turn.
        //
        // Migo batches Canvas2D commands and resolves them at frame
        // boundaries, so a burst of draw-then-getImageData inside a single JS
        // turn is not what any real game does and not what the suite should
        // measure. Driving each test from its own rAF keeps every assertion on
        // the path content actually uses -- and stops the suite reporting
        // engine faults that are really artefacts of its own batching.
        // A body may return a promise, and then the next test does not start
        // until it settles. Lifecycle tests need this and pixel tests do not:
        // "the page went hidden and came back" is an event that arrives when the
        // host decides, not something a test body can drive to completion inside
        // one turn. Awaiting a non-promise is a microtask, so a synchronous body
        // still gets exactly one test per frame and its timing is unchanged --
        // which is why this is safe to add under the existing suites rather than
        // being a second runner they would drift away from.
        let index = 0;
        const step = async () => {
            if (index >= tests.length) {
                done();
                return;
            }
            const [id, body] = tests[index++];
            try {
                await body();
            } catch (error) {
                check(id, false, `threw ${error && error.name}: ${error && error.message}`);
            }
            requestAnimationFrame(step);
        };
        requestAnimationFrame(step);
    }

    // Deliberately a plain script assigned onto the global, not an ES module.
    //
    // Module resolution is exactly the kind of thing that can differ between a
    // bundle loaded by the Android SDK, a C-ABI host, and the Linux player -- and a
    // harness whose own loading is platform-dependent cannot tell you whether the
    // *engine* is platform-dependent. `build.sh` concatenates this ahead of each
    // test, so there is no resolution step at all.

    // Wrapped in an IIFE because build.sh concatenates this ahead of the test
    // in one scope: without it, a test writing `const { check } = ...` collides
    // with the harness's own `check` and the bundle dies at parse time with
    // "Identifier 'check' has already been declared". Caught on the runner's
    // first execution -- by the "no DONE line means failure" rule, which is the
    // one thing standing between this suite and reporting success for a bundle
    // that never ran.
    globalThis.Conformance = { check, checkPixel, checkSameRender, run, done, PREFIX };
})();

// getImageData must return what was drawn, whatever was drawn.
//
// Found by this suite on its first run against the Linux player: a fill
// covering roughly a tenth of the surface or more -- but not all of it --
// makes the *whole* canvas read back as [0,0,0,0], including regions the fill
// never touched, and including a full-surface bulk read. A full-surface fill is
// fine; so is a large fill in one dimension only. The signature points at a
// coverage heuristic with a separate full-surface branch.
//
// It matters because readback is not a debug feature: content generates sprite
// textures with it (Migo's own bunnymark does), does hit testing with it, and
// builds image effects on it. Silent empty buffers there produce blank sprites
// and wrong collisions, with nothing logged anywhere.
//
// Sizes are fractions of the surface so this keeps meaning on any screen.

const C = globalThis.Conformance;
const canvas = migo.createCanvas();
const ctx = canvas.getContext("2d");
const W = canvas.width;
const H = canvas.height;

const clear = () => {
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.fillStyle = "#000000";
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
};

// Fill w x h from the origin, then read one pixel well inside it.
const fillAndRead = (id, w, h) => {
    clear();
    ctx.fillStyle = "#ff00ff";
    ctx.fillRect(0, 0, w, h);
    const px = ctx.getImageData(2, 2, 1, 1).data;
    C.check(
        id,
        px[0] === 255 && px[1] === 0 && px[2] === 255 && px[3] === 255,
        `filled ${w}x${h} (${((w * h * 100) / (W * H)).toFixed(1)}% of surface), ` +
        `read [${px[0]},${px[1]},${px[2]},${px[3]}] at (2,2)`,
    );
};

const frac = (fw, fh) => [Math.max(4, Math.floor(W * fw)), Math.max(4, Math.floor(H * fh))];

C.run([
    ["readback/small-fill", () => fillAndRead("readback/small-fill", ...frac(0.1, 0.05))],
    ["readback/wide-thin-fill", () => fillAndRead("readback/wide-thin-fill", ...frac(0.5, 0.1))],
    ["readback/narrow-tall-fill", () => fillAndRead("readback/narrow-tall-fill", ...frac(0.18, 0.5))],
    // The three that fail today.
    ["readback/quarter-surface-fill", () => fillAndRead("readback/quarter-surface-fill", ...frac(0.5, 0.5))],
    ["readback/half-surface-fill", () => fillAndRead("readback/half-surface-fill", ...frac(0.5, 1.0))],
    ["readback/full-surface-fill", () => fillAndRead("readback/full-surface-fill", W, H)],

    ["readback/untouched-region-keeps-its-background", () => {
        // The sharpest form: the failure is not "the fill did not land", it is
        // that the *entire* buffer comes back empty. This samples a region the
        // fill never covered, which must still be the background it was
        // cleared to.
        clear();
        ctx.fillStyle = "#ff00ff";
        const [w, h] = frac(0.5, 0.5);
        ctx.fillRect(0, 0, w, h);
        const px = ctx.getImageData(W - 2, H - 2, 1, 1).data;
        C.check(
            "readback/untouched-region-keeps-its-background",
            px[3] === 255,
            `far corner after a ${w}x${h} fill: [${px[0]},${px[1]},${px[2]},${px[3]}] (alpha must be 255)`,
        );
    }],

    ["readback/bulk-read-matches-single-pixel", () => {
        // A whole-surface read and a one-pixel read must agree. If they do not,
        // content that batches its readback sees something different from
        // content that samples -- and only one of them is being tested by the
        // rest of this file.
        clear();
        ctx.fillStyle = "#ff00ff";
        const [w, h] = frac(0.5, 0.5);
        ctx.fillRect(0, 0, w, h);
        const one = ctx.getImageData(2, 2, 1, 1).data;
        const all = ctx.getImageData(0, 0, W, H).data;
        const i = (2 * W + 2) * 4;
        const same = [0, 1, 2, 3].every((k) => one[k] === all[i + k]);
        C.check(
            "readback/bulk-read-matches-single-pixel",
            same,
            `single [${one[0]},${one[1]},${one[2]},${one[3]}] vs bulk ` +
            `[${all[i]},${all[i + 1]},${all[i + 2]},${all[i + 3]}]`,
        );
    }],
]);
